              <form id="contact-form" novalidate>
                ${Field({
                  id: "fullName",
                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name",
                  placeholder: "Jordan Lee",
                })}
                <div class="split">
                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    required: true,
                    autocomplete: "email",
                    placeholder: "jordan@example.com",
                  })}
                  ${Field({
                    id: "phone",
                    label: "Phone number",
                    type: "tel",
                    required: false,
                    autocomplete: "tel",
                    placeholder: "(555) 123-4567",
                    helpText:
                      "Format: (555) 123-4567 or +1 555 123 4567. Optional.",
