                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name",
                  placeholder: "Jordan Lee",
                })}
                <div class="split">
                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    required: true,
                    autocomplete: "email",
                    placeholder: "jordan@example.com",
                  })}
                  ${Field({
                    id: "phone",
                    label: "Phone number",
                    type: "tel",
                    required: false,
                    autocomplete: "tel",
                    placeholder: "(555) 123-4567",
                    helpText:
                      "Format: (555) 123-4567 or +1 555 123 4567. Optional.",
                  })}
                </div>
                <div class="actions">
                  <button type="submit">Submit request</button>
                  <p class="status" id="form-status" aria-live="polite"></p>
                </div>
              </form>
            </section>
          </main>
          <footer>
            <p>We only use the details you share here to respond to your support request.</p>
          </footer>
        `;
      }

      function Field({
        id,
        label,
        type,
        required,
        autocomplete,
        placeholder,
        helpText = "",
      }) {
        const error = state.errors[id] || "";
        const touched = state.touched[id];
        const showError = Boolean(error) && (touched || submitted);
        const describedIds = describedBy(id, showError, helpText ? [`${id}-help`] : []);
        return `
