            <label for="${id}">
              ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              ${required ? "required" : ""}
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              value="${escapeHtml(state.values[id])}"
              aria-describedby="${describedIds}"
              ${showError ? 'aria-invalid="true"' : ""}
            />
            ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
            <p class="field-error" id="${id}-error" aria-live="polite">${showError ? escapeHtml(error) : ""}</p>
          </div>
        `;
      }

      let submitted = false;

      function syncField(id) {
        const input = els[id];
