  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        errors: {},
      };

      const els = {};

      function escapeHtml(value) {
        return value
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
      }

      function validate(values) {
        const errors = {};
        const fullName = values.fullName.trim();
        const email = values.email.trim();
        const phone = values.phone.trim();

        if (!fullName) {
          errors.fullName = "Please enter your full name.";
        }

        if (!email) {
          errors.email = "Please enter your email address.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          errors.email = "Enter a valid email address, like name@example.com.";
        }

        if (phone && !/^\+?[0-9][0-9\s().-]{6,}[0-9]$/.test(phone)) {
          errors.phone =
            "Use the phone format (555) 123-4567 or +1 555 123 4567.";
        }

        return errors;
      }

      function describedBy(id, hasError, extraIds = []) {
        const ids = [...extraIds];
        if (hasError) {
          ids.push(`${id}-error`);
        }
        return ids.join(" ");
      }

      function describedByAttr(id, hasError, helpText = "") {
        const ids = [];
        if (helpText) {
          ids.push(`${id}-help`);
        }
        if (hasError) {
          ids.push(`${id}-error`);
        }
        return ids.length ? `aria-describedby="${ids.join(" ")}"` : "";
      }

      function App() {
        return `
          <header>
            <p class="eyebrow">Support</p>
            <h1>Contact our support team</h1>
            <p class="intro">
              Share your details below and we&apos;ll route your request to the
              right person.
            </p>
          </header>
          <main id="main-content">
            <section class="panel" aria-labelledby="contact-form-title">
              <h2 id="contact-form-title" class="sr-only">Contact form</h2>
              <form id="contact-form" novalidate>
                ${Field({
                  id: "fullName",
                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name",
                  placeholder: "Jordan Lee",
                })}
                <div class="split">
                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    required: true,
                    autocomplete: "email",
                    placeholder: "jordan@example.com",
                  })}
                  ${Field({
                    id: "phone",
                    label: "Phone number",
                    type: "tel",
                    required: false,
                    autocomplete: "tel",
                    placeholder: "(555) 123-4567",
                    helpText:
                      "Format: (555) 123-4567 or +1 555 123 4567. Optional.",
                  })}
                </div>
                <div class="actions">
                  <button type="submit">Submit request</button>
                  <p class="status" id="form-status" aria-live="polite"></p>
                </div>
              </form>
            </section>
          </main>
          <footer>
            <p>We only use the details you share here to respond to your support request.</p>
          </footer>
        `;
      }

      function Field({
        id,
        label,
        type,
        required,
        autocomplete,
        placeholder,
        helpText = "",
      }) {
