        const error = state.errors[id] || "";
        const showError = Boolean(error) && (state.touched[id] || submitted);
        const describedIds = describedByAttr(id, showError, id === "phone" ? "format" : "");
        if (describedIds) {
          input.setAttribute("aria-describedby", describedIds.replace('aria-describedby="', "").replace('"', ""));
        } else {
          input.removeAttribute("aria-describedby");
        }
        if (showError) {
          input.setAttribute("aria-invalid", "true");
          errorNode.textContent = error;
        } else {
          input.removeAttribute("aria-invalid");
          errorNode.textContent = "";
        }
      }

      function syncAll() {
        state.errors = validate(state.values);
        ["fullName", "email", "phone"].forEach(syncField);
      }

      function handleInput(event) {
        const { id, value } = event.target;
        state.values[id] = value;
        if (submitted || state.touched[id]) {
          state.errors = validate(state.values);
          syncField(id);
        }
      }

      function handleBlur(event) {
        const { id } = event.target;
        state.touched[id] = true;
        state.errors = validate(state.values);
        syncField(id);
      }

      function handleSubmit(event) {
        event.preventDefault();
        submitted = true;
        state.touched.fullName = true;
        state.touched.email = true;
        state.touched.phone = true;
        state.errors = validate(state.values);
        syncAll();

        const firstInvalidId = ["fullName", "email", "phone"].find((id) => state.errors[id]);
        const status = document.getElementById("form-status");

        if (firstInvalidId) {
          status.textContent = "Please fix the highlighted fields and try again.";
          els[firstInvalidId].focus();
          return;
        }

        status.textContent = "All details look good. Your request is ready to submit.";
      }

      function mount() {
        document.getElementById("root").innerHTML = App();
        els.fullName = document.getElementById("fullName");
        els.email = document.getElementById("email");
        els.phone = document.getElementById("phone");

        ["fullName", "email", "phone"].forEach((id) => {
          els[id].addEventListener("input", handleInput);
          els[id].addEventListener("blur", handleBlur);
        });

        document.getElementById("contact-form").addEventListener("submit", handleSubmit);
        syncAll();
      }

      mount();
    </script>
