    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
