                  id: "fullName",
                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name",
                  placeholder: "Jordan Lee",
                })}
                <div class="split">
                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    required: true,
                    autocomplete: "email",
                    placeholder: "jordan@example.com",
                  })}
                  ${Field({
                    id: "phone",
                    label: "Phone number",
                    type: "tel",
                    required: false,
                    autocomplete: "tel",
                    placeholder: "(555) 123-4567",
                    helpText:
                      "Format: (555) 123-4567 or +1 555 123 4567. Optional.",
                  })}
                </div>
                <div class="actions">
                  <button type="submit">Submit request</button>
                  <p class="status" id="form-status" aria-live="polite"></p>
                </div>
              </form>
            </section>
          </main>
          <footer>
            <p>We only use the details you share here to respond to your support request.</p>
          </footer>
        `;
      }

      function Field({
        id,
        label,
        type,
        required,
        autocomplete,
        placeholder,
        helpText = "",
      }) {
        const error = state.errors[id] || "";
        const touched = state.touched[id];
        const showError = Boolean(error) && (touched || submitted);
        const describedIds = describedByAttr(id, showError, helpText);
        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              ${required ? "required" : ""}
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              value="${escapeHtml(state.values[id])}"
              ${describedIds}
              ${showError ? 'aria-invalid="true"' : ""}
            />
            ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
            <p class="field-error" id="${id}-error" aria-live="polite">${showError ? escapeHtml(error) : ""}</p>
          </div>
        `;
      }

      let submitted = false;

      function syncField(id) {
        const input = els[id];
        const errorNode = document.getElementById(`${id}-error`);
        const error = state.errors[id] || "";
        const showError = Boolean(error) && (state.touched[id] || submitted);
        const describedIds = describedByAttr(id, showError, id === "phone" ? "format" : "");
        if (describedIds) {
          input.setAttribute("aria-describedby", describedIds);
        } else {
          input.removeAttribute("aria-describedby");
        }
        if (showError) {
          input.setAttribute("aria-invalid", "true");
          errorNode.textContent = error;
        } else {
          input.removeAttribute("aria-invalid");
          errorNode.textContent = "";
        }
